pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // Restrict feeRate to be above 5000 to target the buggy behavior.
        vm.assume(_feeRate > 5000);

        // Attempt to initialize the contract.
        bool initializedOk;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            initializedOk = true;
        } catch {
            initializedOk = false;
        }

        // General rule: After initialize completes successfully, feeRate must be <= 5000.
        // The reference reverts (initializedOk == false) for feeRate > 5000,
        // while the buggy version succeeds and stores a value > 5000.
        assertTrue(!initializedOk || c.feeRate() <= 5000);
    }
}

